import heapq

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    edges = []
    for i in range(m):
        u, v, w = map(int, lines[1 + i].split())
        edges.append((u, v, w, i + 1))  # Store edge index (1-based)

    start = int(lines[1 + m])

    # Adjacency list
    adj = [[] for _ in range(n + 1)]
    for u, v, w, idx in edges:
        adj[u].append((v, w, idx))
        adj[v].append((u, w, idx))

    # Dijkstra from start
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w, idx in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    # For each vertex except start, find the edge with minimum weight
    # that satisfies dist[u] + w = dist[v]
    ans_edges = []
    total_weight = 0

    for v in range(1, n + 1):
        if v == start:
            continue

        best_idx = -1
        best_w = float('inf')

        # Iterate through all edges to find the best one for vertex v
        for u1, u2, w, idx in edges:
            # Check if this edge can be used to reach v
            if u1 == v:
                # Edge is (u2, v) or (v, u2)
                if dist[u2] + w == dist[v] and dist[u2] != float('inf'):
                    if w < best_w:
                        best_w = w
                        best_idx = idx
            elif u2 == v:
                # Edge is (u1, v) or (v, u1)
                if dist[u1] + w == dist[v] and dist[u1] != float('inf'):
                    if w < best_w:
                        best_w = w
                        best_idx = idx

        if best_idx != -1:
            ans_edges.append(best_idx)
            total_weight += best_w

    # Output
    result = f"{total_weight}\n{' '.join(map(str, ans_edges))} "
    return result

