def solution(data: str) -> str:
    parts = list(map(int, data.strip().split()))
    n, p, l, r = parts[0], parts[1], parts[2], parts[3]

    def modinv(a, m):
        return pow(a, m - 2, m)

    def C(n, k, mod):
        if k < 0 or k > n:
            return 0
        num = 1
        den = 1
        for i in range(k):
            num = (num * (n - i)) % mod
            den = (den * (i + 1)) % mod
        return (num * modinv(den, mod)) % mod

    ans = 0

    for a in range(n + 1):
        for b in range(n - a + 1):
            a_b = a - b
            if a < b:
                continue
            if not (l <= a_b <= r):
                continue
            c = n - a - b
            ways_ab = ((a - b + 1) * modinv(a + 1, p)) % p
            ways_AB = C(a + b, a, p)
            ways_total = (C(n, c, p) * ways_AB * ways_ab) % p
            ans = (ans + ways_total) % p

    return str(ans)

