        return '\n'

    t = tokens[idx]
    idx += 1

    results = []

    for _ in range(t):
        if idx >= len(tokens):
            break
        n = tokens[idx]
        idx += 1

        # Parse the tree structure
        tree = [None] * n
        for i in range(n):
            if idx < len(tokens) and tokens[idx] == -1:
                l, r = tokens[idx + 1], tokens[idx + 2]
                idx += 3
                tree[i] = ('internal', l, r)
            else:
                val = tokens[idx]
                idx += 1
                tree[i] = ('leaf', val)

        # Count leaves in subtree
        def count_leaves(u):
            if tree[u][0] == 'leaf':
                return 1
            return count_leaves(tree[u][1]) + count_leaves(tree[u][2])

        from functools import lru_cache

        @lru_cache(maxsize=None)
        def solve(u):
            if tree[u][0] == 'leaf':
                return tree[u][1]

            left, right = tree[u][1], tree[u][2]
            leaves_left = count_leaves(left)
            leaves_right = count_leaves(right)
            leaves_total = leaves_left + leaves_right

            # Recursive calls with proper turn tracking
            val_left = solve(left)
            val_right = solve(right)

            # The merge at this node contributes based on total leaf count
            if leaves_total % 2 == 1:
                # Odd number of leaves: achievable max/min through one merge
                return max(min(val_left, val_right))
            else:
                # Even number: the game structure allows max
                return min(val_left, val_right) if leaves_total >= 2 else max(val_left, val_right)

        result = solve(0)
        results.append(str(result))

    return '\n'.join(results) + '\n'

