MOD = 10**9 + 7
MAX_N = 300005

fact = [1] * MAX_N
inv = [1] * MAX_N

def precompute():
    global fact, inv
    for i in range(2, MAX_N):
        fact[i] = (fact[i-1] * i) % MOD

    inv[MAX_N - 1] = pow(fact[MAX_N - 1], MOD - 2, MOD)
    for i in range(MAX_N - 2, 1, -1):
        inv[i] = (inv[i+1] * (i+1)) % MOD

precompute()

def nCr(n, r):
    if r < 0 or r > n:
        return 0
    return fact[n] * inv[r] % MOD * inv[n-r] % MOD

def count_ways(t, k, s):
    """Count ways to get sum s after t turns where each turn gives [-k, k]"""
    S_actual = s + t * k
    if S_actual < 0 or S_actual > t * 2 * k:
        return 0

    ans = 0
    L = S_actual // (2 * k + 1)
    for j in range(L + 1):
        sign = 1 if j % 2 == 0 else -1
        S_adj = S_actual - j * (2 * k + 1)
        term = nCr(S_adj + t - 1, t - 1) * nCr(t, j) % MOD
        if sign == 1:
            ans = (ans + term) % MOD
        else:
            ans = (ans - term + MOD) % MOD

    return ans

def solution(input_str):
    a, b, k, t = map(int, input_str.strip().split())

    if k == 0:
        return '1' if a > b else '0'

    max_sum = t * k
    diff = b - a  # We need X > Y + diff

    # Compute distribution of X (and Y, same distribution)
    offset = max_sum
    dp = [0] * (2 * max_sum + 1)
    dp[offset] = 1  # After 0 turns, sum is 0

    for turn in range(t):
        new_dp = [0] * (2 * max_sum + 1)
        # Convolve with uniform [-k, k]
        # For each previous sum s, we add values from -k to k
        for i in range(2 * max_sum + 1):
            if dp[i] == 0:
                continue
            for val in range(-k, k + 1):
                new_idx = i + val
                if 0 <= new_idx < 2 * max_sum + 1:
                    new_dp[new_idx] = (new_dp[new_idx] + dp[i]) % MOD
        dp = new_dp

    # Compute prefix sums for efficient range queries
    prefix = [0] * (2 * max_sum + 2)
    for i in range(2 * max_sum + 1):
        prefix[i + 1] = (prefix[i] + dp[i]) % MOD

    # Count winning pairs (X, Y) where X > Y + diff
    # For each X, valid Y: Y < X - diff
    # Y ranges in [-max_sum, max_sum]

    ans = 0
    for x in range(2 * max_sum + 1):
        if dp[x] == 0:
            continue

        # Maximum Y that satisfies: Y < (x - offset) - diff
        max_y_real = (x - offset) - diff - 1
        max_y_idx = min(max_y_real + offset, 2 * max_sum)
        min_y_idx = max(0, -max_sum + offset)

        if max_y_idx >= min_y_idx:
            ways_y = (prefix[max_y_idx + 1] - prefix[min_y_idx] + MOD) % MOD
            ways_x = dp[x]
            ans = (ans + ways_y * ways_x) % MOD

    return str(ans)

