    components = []

    for i in range(1, n + 1):
        if i not in visited:
            queue = deque([i])
            visited.add(i)
            size = 0
            while queue:
                node = queue.popleft()
                size += 1
                for neighbor in adj[node]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append(neighbor)
            components.append(size)

    def is_lucky(num):
        s = str(num)
        return all(c in '47' for c in s)

    for c in components:
        if is_lucky(c):
            return '0'

    lucky_numbers = []
    q = deque([4, 7])
    while q:
        num = q.popleft()
        if num <= n:
            lucky_numbers.append(num)
            if num * 10 <= n:
                q.append(num * 10)
            if num * 10 + 4 <= n:
                q.append(num * 10 + 4)
            if num * 10 + 7 <= n:
                q.append(num * 10 + 7)

    dp = {0: 0}
    for size in components:
        new_sums = {}
        for s, count in dp.items():
            ns = s + size
            if ns not in dp or count + 1 < dp[ns]:
                new_sums[ns] = count + 1

        for ns, cnt in new_sums.items():
            if ns not in dp or cnt < dp[ns]:
                dp[ns] = cnt

    result = min((dp.get(l, float('inf')) for l in lucky_numbers), default=float('inf'))

    if result == float('inf'):
