def solution(input_string):
    import itertools

    # Parse input
    lines = input_string.strip().split('\n')

    # Extract dimensions
    n, m = map(int, lines[0].split())

    # Parse table A
    A = []
    for i in range(n):
        A.append(list(map(int, lines[i + 1].split())))

    # Parse table B
    B = []
    for i in range(n):
        B.append(list(map(int, lines[n + 1 + i].split())))

    # If already equal, no sorting needed
    if A == B:
        return "0"

    # Check if columns have the same multisets of values
    # This is a necessary condition
    for j in range(m):
        a_col_sorted = sorted([row[j] for row in A])
        b_col_sorted = sorted([row[j] for row in B])
        if a_col_sorted != b_col_sorted:
            return "-1"

    def apply_sort(table, sort_cols):
        """Sort table rows by given column sequence (stable sort)"""
        n_rows = len(table)
        indices = list(range(n_rows))
        for c in sort_cols:
            # Stable sort by column c
            indices.sort(key=lambda i: table[i][c])
        return [table[i] for i in indices]

    result = None

    # Try single column sorts first
    for c in range(m):
        if apply_sort(A, [c]) == B:
            result = [c + 1]
            break

    # Try pairs of column sorts
    if result is None:
        for i in range(m):
            for j in range(m):
                if i == j:
                    continue
                if apply_sort(A, [i, j]) == B:
                    result = [i + 1, j + 1]
                    break
            if result is not None:
                break

    # Try triples of column sorts (up to reasonable limit)
    if result is None and m > 2:
        for i in range(m):
            for j in range(m):
                if j == i:
                    continue
                for k in range(m):
                    if k == i or k == j:
                        continue
                    if apply_sort(A, [i, j, k]) == B:
                        result = [i + 1, j + 1, k + 1]
                        break
                if result is not None:
                    break
            if result is not None:
                break

    # Try longer sequences up to a limit (5000 per problem)
    if result is None:
        # Try permutations of columns
        for length in range(4, min(m + 1, 11)):
            for seq in itertools.permutations(range(m), length):
                if apply_sort(A, seq) == B:
                    result = list(seq) + seq[0:0]  # just the columns
                    break
            if result is not None:
                break

    # Final fallback: try all column sorts up to k=5000
    if result is None:
        for cols_seq in itertools.permutations(range(m), min(m, 10)):
            seq_result = apply_sort(A, cols_seq)
            if seq_result == B:
                result = [c + 1 for c in cols_seq]
                break

    if result is not None:
        return f"{len(result)}\n{' '.join(map(str, result))}"
    return "-1"

