            new_dp = [float('inf')] * (len(dp) + len(child_dp) - 1)

            for i in range(len(dp)):
                for j in range(len(child_dp)):
                    new_dp[i + j] = min(new_dp[i + j], dp[i] + child_dp[j])

            dp = new_dp

        return dp

    # Process tree
    order = list(range(1, n + 1))

    items = [(None, None)]  # dummy at index 0
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        ci = parts[0]
        di = parts[1]
        items.append((ci, ci - di))

    # Post-order processing
    visited = [False] * (n + 1)

    def post_order(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                post_order(v)

