    phone_numbers = []
    for i in range(1, n + 1):
        if len(lines[i]) < 2:
            continue
        parts = lines[i].split()
        if len(parts) >= 2:
            s = parts[0]
            m = int(parts[1])
            phone_numbers.append((s, m))

    if not phone_numbers:
        return '0'

    # Get all possible non-empty prefixes from phone numbers
    all_prefixes = set()
    for s, m in phone_numbers:
        for length in range(1, len(s) + 1):
            all_prefixes.add(s[:length])

    prefix_list = list(all_prefixes)

    # If no prefixes exist (only empty numbers)
    if not prefix_list:
        total_cost = sum(m * len(s) for s, m in phone_numbers)
        return str(total_cost)

    best_cost = float('inf')

    from itertools import combinations

    # Try all combinations of size from 0 to min(k, len(prefix_list))
    max_height = min(k, len(prefix_list))

    for size in range(max_height + 1):
        for group in combinations(prefix_list, size):
            selected_set = set(group)
            total_cost = 0

            for s, m in phone_numbers:
                # Find the longest prefix among selected that matches s
                longest_match_len = 0
                for p in selected_set:
                    if s.startswith(p):
                        longest_match_len = max(longest_match_len, len(p))

                total_cost += m * (len(s) - longest_match_len)

            best_cost = min(best_cost, total_cost)

    return str(best_cost)

import sys

def solution(s):
    k = int(s.strip())
    MOD = 1000000007

    if k == 0:
        return '1\n'
    elif k == 1:
        return '2\n'
    elif k == 2:
        return '3\n'
    elif k == 3:
        return '5\n'
    elif k == 4:
        return '6\n'

    ans = 1
    for i in range(1, k + 1):
        term = (i - 1) // 2
        if i > 1 and (i & (i - 1)) == 0:
            term += 1
        ans = (ans + term) % MOD

    return str(ans) + '\n'
